export const PermanentMarker = localFont({
  src: [
    {
      path: './PermanentMarker-Regular.ttf',
      weight: '400',
      style: 'normal',
    },
  ],
  variable: '--font-permanent-marker',
});

import './globals.css';

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode;
}>) {
  return (
    <html className={`${PermanentMarker.variable} antialiased`}>
      <body>{children}</body>
    </html>
  );
}
```

```css
/* globals.css */
